#requires -Version 5.1
[CmdletBinding()]
param(
 [string]$AppDataRoot=(Join-Path $env:LOCALAPPDATA 'StockRecommendationEngine'),
 [string]$EngineRoot='',
 [string]$OutputDirectory=(Join-Path $HOME 'Downloads'),
 [string]$PythonPath='',
 [string]$RollbackDirectory=''
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$utf8=New-Object Text.UTF8Encoding($false)
$collectorBytes=[Convert]::FromBase64String('')
$workerBytes=[Convert]::FromBase64String('')
$guardBytes=[Convert]::FromBase64String('')
function Inside([string]$p,[string]$parent) { return $p.Equals($parent,[StringComparison]::OrdinalIgnoreCase) -or $p.StartsWith($parent.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase) }
function Test-SreInside([string]$Path, [string]$Parent) {
    return $Path.Equals($Parent, [StringComparison]::OrdinalIgnoreCase) -or
        $Path.StartsWith($Parent.TrimEnd('\','/') + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)
}
function Assert-SreStopped([string]$DataRoot, [string]$InstallRoot) {
    # Parse Windows argv and expand hybrid long/8.3 directory aliases before matching.
    if(-not ('SreContinuityProcessPaths' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
public static class SreContinuityProcessPaths {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern uint GetLongPathName(string path,StringBuilder output,uint size);
 [DllImport("shell32.dll",CharSet=CharSet.Unicode)] static extern IntPtr CommandLineToArgvW(string command,out int count);
 [DllImport("kernel32.dll")] static extern IntPtr LocalFree(IntPtr p);
 static string Long(string p) {var b=new StringBuilder(32768);return GetLongPathName(p,b,32768)>0?b.ToString():Path.GetFullPath(p);}
 public static bool References(string command,string root) {
  if(String.IsNullOrEmpty(command))return false;
  int count;IntPtr p=CommandLineToArgvW(command,out count);if(p==IntPtr.Zero)return false;
  try {string target=Long(root).TrimEnd('\\','/');for(int i=0;i<count;i++) {
   string arg=Marshal.PtrToStringUni(Marshal.ReadIntPtr(p,i*IntPtr.Size));
   if(!Directory.Exists(arg)&&!File.Exists(arg))continue;
   string path=Long(arg);if(path.Equals(target,StringComparison.OrdinalIgnoreCase)||path.StartsWith(target+"\\",StringComparison.OrdinalIgnoreCase))return true;
  }return false;}finally{LocalFree(p);}
 }
}
'@
    }
    # Fail closed if process inventory cannot be read. Never terminate a process.
    $aliases=@($InstallRoot,$DataRoot)
    $fso=New-Object -ComObject Scripting.FileSystemObject
    try { foreach($r in @($InstallRoot,$DataRoot)) { $f=$fso.GetFolder($r); try { $aliases+=@([string]$f.ShortPath,[string]$f.Path) } finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($f) } } }
    finally { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($fso) }
    $processes = @(Get-CimInstance Win32_Process -ErrorAction Stop)
    foreach ($p in $processes) {
        if ($p.ProcessId -eq $PID) { continue }
        $name = [string]$p.Name
        $exe = [string]$p.ExecutablePath
        $cmd = [string]$p.CommandLine
        $isShell = $name -match '^(powershell|pwsh|cmd|conhost)\.exe$'
        $inInstall = $exe -and ((Test-SreInside $exe $InstallRoot) -or (Test-SreInside $exe $DataRoot))
        $namedApp = $name -match '^(StockRecommendationEngine|stock-recommendation-engine|stock_app_launcher|stock_app_ops_launcher|sre)\.exe$'
        $backend = $name -match '^(python[^\/ ]*|uvicorn)(\.exe)?$' -and
            ($cmd -match '(run_modern_ui|stock_app_launcher|stock_app_ops_launcher|modern_ui[./\\:]|uvicorn.+modern_ui)' -or
             (@($aliases | Where-Object { $cmd -and $cmd.Replace('/','\').IndexOf($_.Replace('/','\'),[StringComparison]::OrdinalIgnoreCase) -ge 0 }).Count -gt 0))
        if (($inInstall -and -not $isShell) -or $namedApp -or $backend -or ($name -match "^python" -and [SreContinuityProcessPaths]::References($cmd,$InstallRoot))) {
            throw "SRE appears to be running (PID $($p.ProcessId), $name). Close SRE and rerun this script. No process was stopped."
        }
    }
}

$run=$null
try {
 $AppDataRoot=[IO.Path]::GetFullPath($AppDataRoot)
 if(-not $EngineRoot){$EngineRoot=Join-Path $AppDataRoot 'native-engine-0.14.13'}
 $EngineRoot=[IO.Path]::GetFullPath($EngineRoot)
 $OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory)
 if(Inside $OutputDirectory $AppDataRoot){throw 'Output must be outside application data.'}
 if(-not(Test-Path -LiteralPath $EngineRoot -PathType Container)){throw 'Installed engine missing.'}
 Assert-SreStopped $AppDataRoot $EngineRoot
 if($RollbackDirectory){
  $run=[IO.Path]::GetFullPath($RollbackDirectory)
  if(Inside $run $AppDataRoot){throw 'Rollback evidence directory must be outside application data.'}
  if(-not(Test-Path -LiteralPath (Join-Path $run 'publication.json'))){throw 'Matching publication receipt missing.'}
 }else{
  New-Item -ItemType Directory -Path $OutputDirectory -Force | Out-Null
  $run=Join-Path $OutputDirectory ('SRE-Windows-Continuation-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[Guid]::NewGuid().ToString('N').Substring(0,6))
  New-Item -ItemType Directory -Path $run | Out-Null
 }
 $worker=Join-Path $run 'native-continuation.py';$guard=Join-Path $run 'source-guard.json'
 [IO.File]::WriteAllBytes($worker,$workerBytes);[IO.File]::WriteAllBytes($guard,$guardBytes)
 if($PythonPath){if(-not(Test-Path -LiteralPath $PythonPath -PathType Leaf)){throw 'Requested existing Python not found.'};$py=$PythonPath;$prefix=@()}
 else{$p=Get-Command py.exe -ErrorAction SilentlyContinue;if($p){$py=$p.Source;$prefix=@('-3')}else{$p=Get-Command python.exe -ErrorAction Stop;$py=$p.Source;$prefix=@()}}
 $common=@('--engine',$EngineRoot,'--app',$AppDataRoot,'--output',$run,'--guard',$guard)
 if($RollbackDirectory){
  & $py @prefix $worker '--mode' 'rollback' @common
  if($LASTEXITCODE -ne 0){throw 'Guarded rollback refused; inspect ACCEPTANCE_ERROR.json. No old records are removed.'}
  Write-Host "Rollback retained new evidence in $run\rolled-back-results. Original records and financial databases unchanged."
  exit 0
 }
 # Fresh closed-app snapshot is the private rollback/restore baseline for this execution.
 # This is not a request to upload another diagnostic before work can proceed.
 $collector=Join-Path $run 'capture-baseline.ps1';[IO.File]::WriteAllBytes($collector,$collectorBytes)
 & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $collector -AppDataRoot $AppDataRoot -EngineRoot $EngineRoot -OutputDirectory $run -SkipOfficialDownloads *> (Join-Path $run 'capture.log')
 if($LASTEXITCODE -ne 0){throw 'Consistent backup/preflight failed; no replay publication attempted. See capture.log.'}
 $zips=@(Get-ChildItem -LiteralPath $run -Filter 'SRE-GateBC-ReadOnly-*.zip' -File)
 if($zips.Count -ne 1){throw 'Expected exactly one verified baseline backup.'}
 $snapshot=Join-Path $run 'snapshot'
 Expand-Archive -LiteralPath $zips[0].FullName -DestinationPath $snapshot
 Assert-SreStopped $AppDataRoot $EngineRoot
 # One worker process, no shell command construction, no package installs.
 # The native worker launches a fresh child only for persistent-result reuse.
 & $py @prefix $worker '--mode' 'run' @common '--capture' $snapshot *> (Join-Path $run 'execution.log')
 if($LASTEXITCODE -ne 0){throw 'Continuation stopped safely; inspect execution.log and ACCEPTANCE_ERROR.json. Retain this entire directory.'}
 Write-Host "FINISHED: $run\ACCEPTANCE.md"
 Write-Host 'Native backend recovery is separate from GUI, official-refresh and portable-runtime acceptance. Read all BLOCKED items.'
}catch{
 if($run -and (Test-Path -LiteralPath $run)){
  [IO.File]::WriteAllText((Join-Path $run 'ACCEPTANCE_WRAPPER_ERROR.txt'),($_ | Out-String),$utf8)
 }
 Write-Error $_
 exit 1
}finally{
 if($run -and (Test-Path -LiteralPath $run)){
  $reportZip=$run+'-REPORTS.zip'
  try{
   $reports=@(Get-ChildItem -LiteralPath $run -File | Where-Object {$_.Extension -in '.json','.md','.log','.csv','.txt'})
   if($reports.Count){Compress-Archive -LiteralPath $reports.FullName -DestinationPath $reportZip -Force;Write-Host "PRIVATE ACCEPTANCE REPORTS: $reportZip"}
  }catch{Write-Warning 'Could not zip reports. All originals retained in the run directory.'}
 }
}
